def solve():
    s = input().strip()
    n = len(s)

    # Find all prefix-suffix matches
    prefix_suffix_matches = []
    for l in range(1, n + 1):
        prefix = s[:l]
        suffix = s[n - l:]
        if prefix == suffix:
            prefix_suffix_matches.append(prefix)

    # Count occurrences of each matching prefix as a substring
    prefix_counts = {}  # key: prefix, value: count

    # For each possible starting position
    for i in range(n - len(prefix_suffix_matches[0]) + 1):
        # Check all matching prefixes
        for prefix in prefix_suffix_matches:
            if i + len(prefix) <= n and s[i:i+len(prefix)] == prefix:
                prefix_counts[prefix] = prefix_counts.get(prefix, 0) + 1

    # Output results
    print(len(prefix_suffix_matches))
    for prefix in sorted(prefix_counts.keys()):
        print(f"{len(prefix)} {prefix_counts[prefix]}")

solve()
"}

