format_type = int(input())
original_time = input().strip()

# Parse original time
hour_str = original_time[:2]
minute_str = original_time[3:]

# Generate all valid times for the given format
def get_valid_times(format_type):
    if format_type == 24:
        # 24-hour format: 00 <= hour <= 23, 00 <= minute <= 59
        valid_times = []
        for hour in range(24):
            for minute in range(60):
                valid_times.append(f"{hour:02d}:{minute:02d}")
        return valid_times
    else:  # 12-hour format
        # 12-hour format: 01 <= hour <= 12, 00 <= minute <= 59
        valid_times = []
        for hour in range(1, 13):
            for minute in range(60):
                valid_times.append(f"{hour:02d}:{minute:02d}")
        return valid_times

valid_times = get_valid_times(format_type)

# Find the valid time with minimum differences
def count_changes(original, candidate):
    # Count how many digits are different
    return sum(1 for a, b in zip(original, candidate) if a != b)

min_changes = float('inf')
best_time = original_time

for time in valid_times:
    changes = count_changes(original_time, time)
    if changes < min_changes:
        min_changes = changes
        best_time = time
    elif changes == min_changes:
        # Tie-breaker: prefer the one that appears first alphabetically
        # (we can just keep the first one)
        pass

print(best_time)
"}

