t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    result = []
    for r in range(n):
        # Calculate new residue after moving
        new_residue = (r + a[r]) % n
        result.append(new_residue)

    # Check if the new residues form a permutation of {0, 1, ..., n-1}
    if sorted(result) == list(range(n)):
        print("YES")
    else:
        print("NO")
"}

