import math

def solve():
    n, R, r = map(int, input().split())

    # Special case: only 1 plate can always fit
    if n == 1:
        print("YES")
        return

    # For n > 1, check the condition
    if (R - r) * math.sin(math.pi / n) >= r:
        print("YES")
    else:
        print("NO")

solve()
"}

