# Create a matrix filled with zeroes
matrix = [[0] * n for _ in range(n)]

# Try to place k ones in the matrix
ones_used = 0

# Fill the diagonal first
for i in range(n):
    if ones_used + 1 <= k and matrix[i][i] == 0:
        matrix[i][i] = 1
        ones_used += 1
        if ones_used == k:
            break

# Now fill the upper triangle
for i in range(n):
    for j in range(i + 1, n):
        if ones_used + 2 <= k and matrix[i][j] == 0:
            matrix[i][j] = 1
            matrix[j][i] = 1
            ones_used += 2
            if ones_used == k:
                break
    if ones_used == k:
        break

if ones_used < k:
    print(-1)
else:
    for row in matrix:
        print(' '.join(map(str, row)))
"}

