def solve():
    n, k = map(int, input().split())
    matrix = [[0] * n for _ in range(n)]
    ones_placed = 0

    # Try to fill the matrix lexicographically
    for i in range(n):
        for j in range(n):
            # Skip lower triangle (we'll handle symmetry later)
            if i >= j:
                continue

            # For upper triangle (i < j), we need to consider both positions
            # If we place a 1 at (i, j), we must also place one at (j, i)

            # Can we place a 1 at both positions (i, j) and (j, i)?
            if ones_placed + 2 <= k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                ones_placed += 2
            elif ones_placed + 1 <= k:
                # Can't place at both positions, but maybe place at (i, i) if i == j?
                if i == j:
                    matrix[i][j] = 1
                    ones_placed += 1

    if ones_placed == k:
        for row in matrix:
            print(' '.join(map(str, row)))
    else:
        print(-1)

