import math

MOD = 10**9 + 7

def is_perfect_square(x):
    return int(math.isqrt(x)) ** 2 == x


def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[mask][last] = number of ways to arrange elements in 'mask' ending with 'last'
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: single element
    for i in range(n):
        dp[1 << i][i] = 1

    # DP
    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            for prev in range(n):
                if mask & (1 << prev) and prev != last:
                    if not is_perfect_square(a[prev] * a[last]):
                        dp[mask][last] = (dp[mask][last] + dp[mask ^ (1 << last)][prev]) % MOD

    # Sum all ways to arrange all elements
    result = sum(dp[(1 << n) - 1][last] for last in range(n)) % MOD
    print(result)

solve()
"}

