{"code": "
import sys

# Build graph
adj = {}
edges = []

def add_edge(u, v):
    if u not in adj:
        adj[u] = []
    if v not in adj:
        adj[v] = []
    adj[u].append(v)
    adj[v].append(u)
    edges.append((u, v))

# Read input
lines = sys.stdin.read().strip().split('\n')
n = int(lines[0])
for i in range(1, n + 1):
    parts = lines[i].strip().split()
    u, v = int(parts[0]), int(parts[1])
    add_edge(u, v)

# Find degree 1 nodes (endpoints)
endpoints = []
for city, neighbors in adj.items():
    if len(neighbors) == 1:
        endpoints.append(city)

# If there are 2 endpoints, start from one
# If there are 0 endpoints (all degree 2), we need to choose an arbitrary start
start = endpoints[0] if len(endpoints) == 2 else next(iter(adj))

# Now traverse through the graph
# We need to visit all edges, so we can use DFS
# Build a degree count to track visited edges
degree = {city: len(neighbors) for city, neighbors in adj.items()}

# DFS to find path
path = []

# Helper function to traverse from a city
def dfs(current):
    if len(path) == n + 1:
        return True

    path.append(current)

    # Find the only neighbor that hasn't been used (or has degree 1)
    neighbors = adj[current]
    next_city = None

    # For degree 1 nodes, we already added them to path, so no more neighbors
    if len(neighbors) > 1:
        for neighbor in neighbors:
            if neighbor != path[-2] if len(path) > 1 else True:
                next_city = neighbor
                break

    if next_city is not None:
        if dfs(next_city):
            return True

    # Backtrack
    path.pop()
    return False

if dfs(start):
    print(' '.join(map(str, path)))
else:
    print(' '.join(map(str, path)))
"}

