for cost, a, b in edges:
    if union(parent, rank, a, b):
        min_cost += cost
        edges_used += 1

    if edges_used == n - 1:
        break

# Check if all are connected
if edges_used == n - 1:
    print(min_cost)
else:
    print(-1)
