# Function to compute minimum cost to get a character at position pos
# and what types it provides
# Returns: (cost, digit, letter, symbol) where digit=1 if it's a digit, etc.
def get_char_info(s, pos):
    ch = s[pos - 1]  # convert to 1-indexed
    cost = 0  # cost to move the pointer to this position (just pos-1, since we start at 1)
    digit = 1 if ch.isdigit() else 0
    letter = 1 if ch.isalpha() else 0
    symbol = 1 if ch in ['#', '*', '&'] else 0
    return (cost, digit, letter, symbol)

# Initialize DP
# dp[i][d][l][s] = minimum cost to process first i strings
# with d digits, l letters, s symbols
# i ranges from 0 to n
# d, l, s range from 0 to n
# Since we only need at least 1 of each, we can cap at n
INF = float('inf')
dp = [[[[INF] * (n + 1) for _ in range(n + 1)] for _ in range(n + 1)] for _ in range(n + 1)]

# Base case: no strings processed
for d in range(n + 1):
    for l in range(n + 1):
        for s in range(n + 1):
            dp[0][d][l][s] = INF

# Actually, we need to process first 0 strings with 0 of each type
# dp[0][0][0][0] = 0
# The rest are INF

dp[0][0][0][0] = 0

# Process each string
for i in range(n):
    for d in range(n + 1):
        for l in range(n + 1):
            for s in range(n + 1):
                if dp[i][d][l][s] == INF:
                    continue

                # Try all positions for this string
                for pos in range(1, m + 1):
                    cost, digit, letter, symbol = get_char_info(strings[i], pos)

                    # Update counts
                    new_d = d + digit
                    new_l = l + letter
                    new_s = s + symbol

                    # Update DP
                    new_cost = dp[i][d][l][s] + cost
                    if new_cost < dp[i + 1][new_d][new_l][new_s]:
                        dp[i + 1][new_d][new_l][new_s] = new_cost

# Find the minimum cost with at least 1 of each type
min_total = INF
for d in range(1, n + 1):
    for l in range(1, n + 1):
        for s in range(1, n + 1):
            if dp[n][d][l][s] < min_total:
                min_total = dp[n][d][l][s]

