import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n, k = int(next(it)), int(next(it))
        coords = []

        for _ in range(n):
            x, y = int(next(it)), int(next(it))
            coords.append((x, y))

        # Build graph
        graph = [[] for _ in range(n)]

        for i in range(n):
            xi, yi = coords[i]
            for j in range(i+1, n):
                xj, yj = coords[j]
                if abs(xi - xj) + abs(yi - yj) <= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # Find minimum operations
        min_ops = -1

        for start in range(n):
            # BFS to find minimum operations from this starting point
            visited = [False] * n
            queue = [(start, 0)]
            visited[start] = True
            ops = 0

            while queue:
                pos, _ = queue.pop(0)

                # Charge this point, attract all reachable points
                for neighbor in graph[pos]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, ops + 1))

                # If we've reached all points, return
                if all(visited):
                    ops = ops + 1
                    break

            if all(visited):
                if ops < min_ops or min_ops == -1:
                    min_ops = ops

        print(min_ops)

if __name__ == "__main__":
    solve()

