import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    informed = {0}
    queue = deque()
    if a[0] > 0:
        queue.append(0)
    messages = []
    for i in range(n):
        if i not in informed:
            f = queue.popleft()
            for j in range(n):
                if j not in informed:
                    t = j
                    break
            messages.append((f+1, t+1))
            a[f] -= 1
            informed.add(t)
            if a[t] > 0:
                queue.append(t)
            # If queue empty but not all informed, it's impossible
            if not queue and len(informed) < n:
                print(-1)
                return
    print(len(messages))
    for msg in messages:
        print(msg[0], msg[1])

if __name__ == "__main__":
    solve()
