from collections import deque

def bfs(n, m, grid, k):
    start = None
    target = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    # State: (row, col, frozenset of visited types)
    visited = {}
    queue = deque()

    # (row, col, visited_types, path, distance)
    queue.append((start[0], start[1], frozenset(), [], 0))
    visited[(start[0], start[1], frozenset())] = (0, [])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, types, path, dist = queue.popleft()

        # Check if we reached the target
        if (r, c) == target:
            return path

        # Try all four directions
        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check boundaries
            if 0 <= nr < n and 0 <= nc < m:
                cell = grid[nr][nc]

                # Skip if it's S or T
                if cell == 'S' or cell == 'T':
                    continue

                new_types = set(types)
                if cell != 'S' and cell != 'T':
                    new_types.add(cell)

                # Check if we exceed k types
                if len(new_types) > k:
                    continue

                new_types_frozen = frozenset(new_types)
                new_dist = dist + 1
                new_path = path + [cell]

                state = (nr, nc, new_types_frozen)

                # Check if we've visited this state with a shorter distance
                # or same distance but lexicographically smaller path
                if state not in visited or new_dist < visited[state][0]:
                    visited[state] = (new_dist, new_path)
                    queue.append((nr, nc, new_types_frozen, new_path, new_dist))
                elif new_dist == visited[state][0]:
                    # Same distance, compare paths lexicographically
