from collections import deque

def bfs(n, m, grid, k):
    start = None
    target = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    # State: (row, col, frozenset of visited types)
    visited = {}
    queue = deque()

    # (row, col, visited_types, path, distance)
    queue.append((start[0], start[1], frozenset(), [], 0))
    visited[(start[0], start[1], frozenset())] = (0, [])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Process nodes level by level
    while queue:
        # Process all nodes at current distance
        current_level = []
        while queue:
            r, c, types, path, dist = queue.popleft()
            current_level.append((r, c, types, path, dist))

        # Check if we've reached the target
        for r, c, types, path, dist in current_level:
            if (r, c) == target:
                return path

        # Generate next level
        next_queue = deque()
        next_visited = {}

        for r, c, types, path, dist in current_level:
            # Try all four directions
            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                # Check boundaries
                if 0 <= nr < n and 0 <= nc < m:
                    cell = grid[nr][nc]

                    # Skip if it's S or T
                    if cell == 'S' or cell == 'T':
                        continue

                    new_types = set(types)
                    if cell != 'S' and cell != 'T':
                        new_types.add(cell)

                    # Check if we exceed k types
                    if len(new_types) > k:
                        continue

                    new_types_frozen = frozenset(new_types)
                    new_dist = dist + 1
                    new_path = path + [cell]

                    state = (nr, nc, new_types_frozen)

                    # Check if we've visited this state with a shorter distance
                    # or same distance but lexicographically smaller path
                    if state not in next_visited:
                        next_visited[state] = (new_dist, new_path)
                        next_queue.append((nr, nc, new_types_frozen, new_path, new_dist))
                    else:
                        existing_dist, existing_path = next_visited[state]

                        if new_dist < existing_dist:
                            next_visited[state] = (new_dist, new_path)
                            next_queue.append((nr, nc, new_types_frozen, new_path, new_dist))
                        elif new_dist == existing_dist:
                            # Same distance, compare lexicographically
                            if new_path < existing_path:
                                next_visited[state] = (new_dist, new_path)
                                next_queue.append((nr, nc, new_types_frozen, new_path, new_dist))

        queue = next_queue
        visited = next_visited

    # No path found
    return None

