        for _ in range(n):
            row = set(map(int, data[ptr:ptr + m]))
            rows.append(row)
            ptr += m

        # Read columns
        cols = []
        for _ in range(m):
            col = set(map(int, data[ptr:ptr + n]))
            cols.append(col)
            ptr += n

        # Find the row with all numbers
        all_row = None
        for r in rows:
            if len(r) == n * m:
                all_row = r
                break

        # Find the column with all numbers
        all_col = None
        for c in cols:
            if len(c) == n * m:
                all_col = c
                break

        # Find matching rows and columns
        row_to_col = {}  # row index to column index
        col_to_row = {}  # column index to row index

        # First, match all_row with all_col
        for i, r in enumerate(rows):
            if r == all_row:
                for j, c in enumerate(cols):
                    if c == all_col:
                        row_to_col[i] = j
                        col_to_row[j] = i
                        break
                break

        # Match other rows and columns by shared numbers
        for i, r in enumerate(rows):
            if i == row_to_col.keys():
                continue
            for j, c in enumerate(cols):
                if j == col_to_row.keys():
