                if i == row_to_col.get(i, -1) and j == col_to_row.get(j, -1):
                    # This is where all_row and all_col intersect
                    # The number is the one that appears in both
                    number = rows[i].intersection(cols[j]).pop()
                    matrix[i][j] = number

        # Fill in other positions
        for i in range(n):
