import sys

# Determine distance from source to seat
def get_dist(source, n, m, xp, yp):
    if source == 0:
        return xp + yp  # from (0, 0)
    elif source == m + 1:
        return 2 * (m + 1) - xp - yp  # from (0, m+1)

# Check if assignment is possible
# Sort people by stamina ascending
# For each person, assign to the closest available seat they can reach
# Priority: first source that is "closer" to the seat

def can_assign(n, m, k, stam0, l, stam1):
    # Sort people by stamina ascending
    stam0.sort()
    stam1.sort()

    # List of seats and their distances to each source
    seats = []
    for xp in range(1, n + 1):
        for yp in range(1, m + 1):
            dist0 = xp + yp
            dist1 = 2 * (m + 1) - xp - yp
