def square_free_part(x):
    """Return the square-free part of x."""
    for i in range(2, int(x**0.5) + 1):
        if x % (i*i) == 0:
            x //= (i*i)
    return x


def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Count frequencies of each square-free part
    freq = {}
    for x in a:
        sf = square_free_part(x)
        freq[sf] = freq.get(sf, 0) + 1

    # Get unique square-free parts
    parts = list(freq.keys())
    m = len(parts)

    # DP: dp[mask] = number of ways to arrange parts in mask
    dp = [0] * (1 << m)
    dp[0] = 1

    # For each existing mask, try to extend it by adding a new part
    for mask in range(1 << m):
        for i in range(m):
            if not (mask & (1 << i)):
                # Add part i at the end
                dp[mask | (1 << i)] = (dp[mask | (1 << i)] + dp[mask] * freq[parts[i]]) % MOD

                # Add part i between two existing parts (if they are not the same)
                for j in range(m):
                    if mask & (1 << j) and parts[i] != parts[j]:
                        dp[mask | (1 << i) | (1 << j)] = (dp[mask | (1 << i) | (1 << j)] + dp[mask] * freq[parts[i]] * freq[parts[j]]) % MOD

    # Sum all ways to use all parts
