import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    # Calculate total positions
    total = n * (n + 1) // 2

    if k > total:
        print(-1)
        return

    # Create matrix and used flags
    matrix = [[0] * n for _ in range(n)]
    used = [[False] * n for _ in range(n)]

    # Fill the matrix lexicographically maximal
    for i in range(n):
        for j in range(i + 1):
            # Check if we can place a 1 at (i, j)
            if not used[i][j]:
                if i == j:
                    # Diagonal element, uses 1 one
                    if k >= 1:
                        matrix[i][j] = 1
                        used[i][j] = True
                        k -= 1
                else:
                    # Off-diagonal element, uses 2 ones
                    if k >= 2:
                        matrix[i][j] = 1
                        matrix[j][i] = 1
                        used[i][j] = True
                        used[j][i] = True
                        k -= 2

                if k == 0:
                    break

        if k == 0:
            break

    # Output the matrix
    for row in matrix:
        print(' '.join(map(str, row)) + ' ')

if __name__ == '__main__':
    solve()
