def apply_median_smoothing(sequence):
    """Apply one median smoothing operation to a sequence of 0s and 1s."""
    n = len(sequence)
    if n <= 2:
        return sequence

    # Create new sequence
    new_seq = [0] * n
    new_seq[0] = sequence[0]
    new_seq[-1] = sequence[-1]

    # Apply median smoothing to positions 2 to n-2
    for i in range(1, n-1):
        a, b, c = sequence[i-1], sequence[i], sequence[i+1]

        # Find median
        # Count 0s and 1s
        zeros = 0
        ones = 0
        for val in (a, b, c):
            if val == 0:
                zeros += 1
            else:
                ones += 1

        if zeros >= 2:
            new_seq[i] = 0
        elif ones >= 2:
            new_seq[i] = 1

    return new_seq

def is_stable(sequence):
    """Check if a sequence is stable under median smoothing."""
    if len(sequence) <= 2:
        return True

    for i in range(1, len(sequence)-1):
        a, b, c = sequence[i-1], sequence[i], sequence[i+1]
        if b != a and b != c:
            return False
    return True

def solve():
    n = int(input().strip())
    sequence = list(map(int, input().split()))

    steps = 0

    while not is_stable(sequence):
        sequence = apply_median_smoothing(sequence)
        steps += 1

        # Optimization: if the sequence is not changing, it's stable
        if steps > 2 * n:
            # The maximum number of steps to stabilize is O(n)
            return

    print(steps)
    print(' '.join(map(str, sequence)))

solve()
