from collections import Counter

def is_adorable(freq):
    """Check if a frequency dictionary represents an adorable string"""
    chars = list(freq.keys())
    if len(chars) > 2:
        return False
    if len(chars) == 1:
        return False
    if len(chars) == 2:
        # At least 2 of each
        return freq[chars[0]] >= 2 and freq[chars[1]] >= 2
    return False

def solve():
    s = input().strip()
    freq = Counter(s)
    chars = list(freq.keys())
    n_chars = len(chars)

    # Case: exactly 3 distinct characters
    if n_chars == 3:
        # Try all combinations: {a, b} in group 1, {c} in group 2
        # But group 2 with only one character isn't adorable
        # Try: {a, b} in group 1, {c, one of a or b} in group 2
        # We need at least 2 of each in group 1, and at least 2 of each in group 2
        # Group 2 will have 2 distinct characters

        # Try assigning group 1: chars[0] and chars[1]
        group1_chars = {chars[0], chars[1]}
        remaining_chars = {chars[2]}

        # Need at least 2 of each in group 1
        if freq[chars[0]] >= 2 and freq[chars[1]] >= 2:
            # Remaining: chars[2] and we need at least 2 of chars[2]
            # But group 2 needs to have at least 2 of each of its characters
            # If only one character, it's not adorable
            if freq[chars[2]] >= 2:
                # Both groups have 2 characters each, both groups have at least 2 of each
                # And they're different
                return True

        # Try assigning group 1: chars[0] and chars[2]
        group1_chars = {chars[0], chars[2]}
        remaining_chars = {chars[1]}

        if freq[chars[0]] >= 2 and freq[chars[2]] >= 2:
            if freq[chars[1]] >= 2:
                return True

        # Try assigning group 1: chars[1] and chars[2]
        group1_chars = {chars[1], chars[2]}
        remaining_chars = {chars[0]}

        if freq[chars[1]] >= 2 and freq[chars[2]] >= 2:
            if freq[chars[0]] >= 2:
                return True

        return False

    # Case: exactly 2 distinct characters
    if n_chars == 2:
        if freq[chars[0]] >= 2 and freq[chars[1]] >= 2:
            # Can split into both groups having at least 2 of each
            return True
        return False

    # More than 3 distinct characters
    return False

solve()
