from collections import Counter

def is_adorable(freq):
    """Check if a frequency dictionary represents an adorable string"""
    chars = list(freq.keys())
    if len(chars) > 2:
        return False
    if len(chars) == 1:
        return False
    if len(chars) == 2:
        # At least 2 of each
        return freq[chars[0]] >= 2 and freq[chars[1]] >= 2
    return False

def solve():
    s = input().strip()
    freq = Counter(s)
    chars = list(freq.keys())
    n_chars = len(chars)

    # Case: exactly 3 distinct characters
    if n_chars == 3:
        # Try all combinations: {a, b} in group 1, {c, one of a or b} in group 2
        # Need at least 2 of each in both groups
        # Group 2 will have 2 distinct characters

        # Try assigning group 1: chars[0] and chars[1]
        if freq[chars[0]] >= 2 and freq[chars[1]] >= 2:
            # Remaining: chars[2] and we need at least 2 of chars[2] in group 2
            # Also need at least 1 of chars[0] or chars[1] in group 2
            if freq[chars[2]] >= 2 and (freq[chars[0]] > 2 or freq[chars[1]] > 2):
                return True

