def is_perfect_square(x):
    if x < 0:
        return False
    if x == 0:
        return True
    i = int(x ** 0.5) + 1
    while i * i != x:
        i -= 1
    return i * i == x

def solve():
    MOD = 10**9 + 7
    n = int(input())
    a = list(map(int, input().split()))

    from collections import defaultdict
    count = defaultdict(int)

    for num in a:
        count[num] += 1

    elements = list(count.keys())
    m = len(elements)

    # Map element to index
    element_to_idx = {e: i for i, e in enumerate(elements)}

    # Precompute: can we place element at index i after element at index j?
    # We need to check if element_to_idx[j] * element_to_idx[i] is not a perfect square
    # Actually we need to check if elements[j] * elements[i] is not a perfect square
    can_place = [[False] * m for _ in range(m)]

    for i in range(m):
        for j in range(m):
            if not is_perfect_square(elements[i] * elements[j]):
                can_place[i][j] = True

    # DP: dp[mask][last] = number of ways
    dp = [[0] * m for _ in range(1 << m)]

    # Initialize: single element
    for i in range(m):
        dp[1 << i][i] = 1

    # DP transition
    for mask in range(1, 1 << m):
        for last in range(m):
            if not (mask & (1 << last)):
                continue
            for next_last in range(m):
                if mask & (1 << next_last):
                    continue
                if not can_place[last][next_last]:
                    continue

                dp[mask | (1 << next_last)][next_last] = (dp[mask | (1 << next_last)][next_last] + dp[mask][last]) % MOD

    # Sum all valid permutations
    result = 0
    for i in range(m):
        result = (result + dp[(1 << m) - 1][i]) % MOD

    print(result)

