    """Find the LCM of two strings, or return -1 if it doesn't exist"""

    # Check if the strings have the same set of characters
    if set(s) != set(t):
        return -1

    # Brute force approach: check all combinations up to some limit
    max_repeats = 100
    for i in range(1, max_repeats + 1):
        for j in range(1, max_repeats + 1):
            candidate_s = s * i
            candidate_t = t * j
            if candidate_s == candidate_t:
