import sys
sys.setrecursionlimit(1000000)

def main():
    n = int(sys.stdin.readline())
    stamps = []
    edges = {}

    for _ in range(n):
        u, v = map(int, sys.stdin.readline().split())
        stamps.append((u, v))

        if u not in edges:
            edges[u] = []
        if v not in edges:
            edges[v] = []
        edges[u].append(v)
        edges[v].append(u)

    path = []
    visited = set()

    def dfs(u):
        if len(path) == n + 1:
            return True

        path.append(u)
        visited.add(u)

        for v in edges[u]:
            if v not in visited:
                if dfs(v):
                    return True

        path.pop()
        visited.remove(u)
        return False

    # Try all cities as starting point
    for start in edges:
        if dfs(start):
            print(' '.join(map(str, path)))
            return

