import sys

def main():
    n = int(sys.stdin.readline())
    stamps = []
    edges = {}

    for _ in range(n):
        u, v = map(int, sys.stdin.readline().split())
        stamps.append((u, v))

        if u not in edges:
            edges[u] = []
        if v not in edges:
            edges[v] = []
        edges[u].append(v)
        edges[v].append(u)

    # Find the two endpoint cities (degree 1)
    endpoints = []
    for city, neighbors in edges.items():
        if len(neighbors) == 1:
            endpoints.append(city)

    # Start from one endpoint
    path = [endpoints[0]]
    visited = set([endpoints[0]])

    # Traverse from endpoint
    def dfs(u):
        if len(path) == n + 1:
            return True

        for v in edges[u]:
            if v not in visited:
                path.append(v)
                visited.add(v)
                if dfs(v):
                    return True
                path.pop()
                visited.remove(v)
        return False

