m = int(sys.stdin.readline())
edges = []

for _ in range(m):
    a, b, c = map(int, sys.stdin.readline().split())
    edges.append((c, a, b))

# Sort edges by cost (Kruskal's algorithm)
edges.sort()

# Find MST
parent = [i for i in range(n + 1)]
rank = [1] * (n + 1)
total_cost = 0
edges_used = 0

for edge in edges:
    cost, a, b = edge
    # We can only use edges where supervisor has higher qualification
    # We need to check if we can orient edges properly
    # For now, just try to find MST
    if union(parent, rank, a, b):
        total_cost += cost
        edges_used += 1
        if edges_used == n - 1:
            break

# Check if we formed a tree
if edges_used != n - 1:
    print(-1)
else:
    # Now we need to verify that we can orient edges as a directed tree
    # with root at some node and edges going from higher qualification to lower
    # To do this, we can try to orient edges and check for cycles

    # Create adjacency list
    adj = [[] for _ in range(n + 1)]
    for i, edge in enumerate(edges):
        cost, a, b = edge
        if union(parent, rank, a, b):  # This means we used this edge in MST
            # Orient edges from higher qualification to lower
            if qualities[a-1] > qualities[b-1]:
                adj[a].append((b, cost))
            else:
                adj[b].append((a, cost))

    # Check if we can build a directed tree
    # We can try each node as root
    def has_cycle(root):
        visited = set()
        def dfs(node, parent):
            if node in visited:
