                if dfs(neighbor, node):
                    return False
            return True
        return not dfs(root, -1)

    # Try each node as root
    for i in range(1, n + 1):
        if has_cycle(i):
            # No cycle means we have a tree
            print(total_cost)
            exit()

    print(-1)
