import sys

def solve(n, m, edges, a):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    # Try all possible subsets of nodes up to size 20
    for size in range(1, 21):
        for solution in itertools.combinations(range(n), size):
            valid = True
            for j in range(n):
                # Count presses in neighbors
                count = sum(1 for neighbor in adj[j] if neighbor in solution)

                # If we pressed node j, add 1 more
                if j in solution:
                    count += 1

                if count == a[j]:
                    valid = False
                    break

            if valid:
                print(len(solution))
                print(' '.join(map(str, [x+1 for x in solution])))
                return

    # If no solution found, try a greedy approach
    solution = []

    for i in range(n):
        copy = solution.copy()
        copy.append(i)

        valid = True
        for j in range(n):
            # Count presses in neighbors
            count = sum(1 for neighbor in adj[j] if neighbor in copy)

            # If we pressed node j, add 1 more
            if j in copy:
                count += 1

            if count == a[j]:
                valid = False
                break

        if valid:
            solution = copy

    if len(solution) > 0:
        print(len(solution))
        print(' '.join(map(str, [x+1 for x in solution])))
    else:
        print(-1)

if __name__ == '__main__':
    import itertools
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

