def min_operations(n, k, points):
    if k == 0:
        # No balls can move, so they must already be at the same position
        # But they are distinct, so this is impossible
        return -1

    # Try each ball as the starting point
    min_ops = float('inf')

    # For each ball i
    for i in range(n):
        ops = 0
        current_balls = set(points)

        while len(current_balls) > 1:
            # Find a ball to charge
            # We'll charge the one that can attract the most balls
            best_ball = None
            best_count = 0

            # Try each ball in current_balls
            for ball in current_balls:
                # Count how many other balls are within distance k
                count = 0
                for other in current_balls:
                    if ball == other:
                        continue
                    if abs(ball[0] - other[0]) + abs(ball[1] - other[1]) <= k:
                        count += 1

                if count > best_count:
                    best_ball = ball
                    best_count = count

            if best_ball is None:
                # No balls can attract any others, so impossible
                break

            # Charge best_ball, all balls within distance k move to best_ball
            to_remove = set()
            for other in current_balls:
                if best_ball == other:
                    continue
                if abs(best_ball[0] - other[0]) + abs(best_ball[1] - other[1]) <= k:
                    to_remove.add(other)

            for ball in to_remove:
                current_balls.remove(ball)

            ops += 1

        min_ops = min(min_ops, ops)

    return min_ops if min_ops != float('inf') else -1


