import sys
import re

def parse_time(s):
    # Match "[hh:mm a.m./p.m.]:" part, extract time_str
    match = re.search(r'\[(\d{2}:\d{2} [ap]\.m\.):', s)
    if not match:
        raise ValueError(f"Invalid time format: {s}")
    time_str = match.group(1).strip()
    # parse
    if ":" not in time_str:
        raise ValueError(f"Invalid time format: {s}")
    hh_str, rest = time_str.split(":")
    mm_str, period = rest.split()
    # Convert hh to int
    hh = int(hh_str)
    mm = int(mm_str)
    # 12-hour to 24-hour:
    if period == 'a.m.':
        if hh == 12:
            hh = 0  # 12:00 a.m. => 00:00
        # 1:00 a.m. = 1, ..., 11:00 a.m. = 11
    else:  # p.m.
        if hh == 12:
            hh = 12  # 12:00 p.m. => 12:00
        else:
            hh += 12
    minutes = hh * 60 + mm
    return minutes

def solve():
    n = int(sys.stdin.readline().strip())
    times = []
    for _ in range(n):
        line = sys.stdin.readline().strip()
        times.append(parse_time(line))
    day_count = 1
    last_time = -1
    count = 0
    for t in times:
        if t == last_time:
            if count < 10:
                count += 1
            else:
                day_count += 1
                count = 1
                last_time = t
        elif t > last_time:
            if count < 10:
                count = 1
                last_time = t
            else:
                day_count += 1
                count = 1
                last_time = t
        else:  # t < last_time (wrap)
            # Always start new day
            day_count += 1
            count = 1
            last_time = t
    print(day_count)

if __name__ == '__main__':
    solve()
