def solve():
    t = int(input())
    for _ in range(t):
        n, k, z = map(int, input().split())
        a = list(map(int, input().split()))

        # dp[i][j]: max score starting at index i, with j right moves remaining to the left
        # We need to ensure we don't do two left moves in a row
        # dp[i][j] means we can do j left moves from this point

        INF = -10**18
        dp = [[INF] * (z + 1) for _ in range(n + 1)]  # dp[0][j] is invalid

        # Starting at index 1, we have k moves and z left moves available
        # We can move right from index 1 to index 2, 3, ..., and from there we can move left

        # Base case: at index 1, we have k moves and z left moves available
        # We can move right from index 1 to index 2, but we can't do any left from index 1
        # So after moving right, we are at index 2 and have k-1 moves and z left moves available

        # Since we can't move left from index 1, we only consider moving right
        for move in range(1, k + 1):
            if move == 1:
                # From index 1, move right to index 2
                dp[2][z] = a[1]  # Initial score + a_2
            else:
                # From index i (move i), move right to index i+1
                for i in range(2, n + 1):
                    if move == i:
                        for l in range(z + 1):
                            if dp[i][l] != INF:
                                dp[i + 1][l] = max(dp[i + 1][l], dp[i][l] + a[i])

        # Now consider moving left from index i
        # After moving left, we need to move right before we can move left again
        # So we can only move left if we can move right afterwards

        # For each possible position and each possible left move count
        for i in range(2, n + 1):
            for move in range(k, 0, -1):
                if move == 1:
                    # Can't move left from position i if we've only made 1 move
                    continue

                # After moving left, we must have at least one more move to move right
                for l in range(z):
                    if dp[i][l] != INF:
                        # Move left to i-1, then we need to move right back to i
                        # After these 2 moves, we have move - 2 moves left
                        dp[i - 1][l + 1] = max(dp[i - 1][l + 1], dp[i][l] + a[i - 1])

                        # After moving left and right, we're back at position i
                        dp[i][l + 1] = max(dp[i][l + 1], dp[i][l] + a[i - 1] + a[i])

        # Find maximum score
        max_score = 0
        for l in range(z + 1):
            max_score = max(max_score, dp[1][l])

        print(max_score)

