    input = sys.stdin.read().strip().split()
    data = list(map(int, input))
    idx = 0
    t = data[idx]
    idx += 1

    output = []
    for _ in range(t):
        n = data[idx]
        idx += 1
        a1 = data[idx:idx+n]
        idx += n
        a2 = data[idx:idx+n]
        idx += n

        # Build bipartite graph: edges between row 1 values and row 2 values
        graph = [[] for _ in range(n + 1)]  # graph[k] = list of values that need to be matched to k

        # For each column, add an edge between the two values
        for i in range(n):
            v1, v2 = a1[i], a2[i]
            # v1 needs to be matched to v2 and vice versa
            graph[v1].append(v2)
            graph[v2].append(v1)

        # Find maximum matching using DFS
        match_to = [-1] * (n + 1)  # match_to[v] = matched to which value
        result = 0

        def dfs(v, visited):
            for neighbor in graph[v]:
                if visited[neighbor] is False:
                    visited[neighbor] = True
                    if match_to[neighbor] == -1 or dfs(match_to[neighbor], visited):
                        match_to[neighbor] = v
                        return True
            return False

        for v in range(1, n + 1):
            visited = [False] * (n + 1)
            if dfs(v, visited):
                result += 1

        # Build swap positions
        swap_positions = []
        # If a value is matched, we need to swap the column that contains the pair
        for v in range(1, n + 1):
            if match_to[v] != -1 and v == match_to[v]:
