                    if a2[i] == match_to[v]:
                        found_match = i
                if found_v == found_match:
                    # They're in the same column, we need to swap it
                    swap_positions.append(found_v + 1)
                else:
                    # They're in different columns
                    pass

        # Now check if both rows are permutations
        row1 = a1.copy()
        row2 = a2.copy()
        for i in range(n):
