def find_optimal_subsequence(a, k):
    """Find the optimal subsequence of length k."""
    n = len(a)

    # dp[i][j]: the optimal value for the i-th position in the subsequence,
    # given that we're considering the first j elements of the array and need to select elements from positions j onwards
    dp = [[None] * (n + 1) for _ in range(k + 1)]

    # Base case: if we need to select 0 elements, nothing to do
    for j in range(n + 1):
        dp[0][j] = []  # Empty subsequence

    # Fill dp table from bottom up
    for i in range(1, k + 1):
        for j in range(n, 0, -1):
            # Option 1: Don't select the j-th element
            option1 = dp[i][j+1]

            # Option 2: Select the j-th element as the i-th element
            if n - j + 1 >= k - i + 1:
                # There are enough elements left to complete the subsequence
                subseq_with_j = [a[j-1]] + dp[i-1][j+1]
                option2 = subseq_with_j
            else:
                option2 = None

            # Choose the lexicographically minimal subsequence among options
            if option1 is None:
                dp[i][j] = option2
            elif option2 is None:
                dp[i][j] = option1
            else:
                # Compare lexicographically
                if option1 < option2:
                    dp[i][j] = option1
                else:
                    dp[i][j] = option2

    return dp[k][1]

