from collections import deque

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    queue = deque()
    queue.append(1)
    a[0] -= 1  # Polycarp sends a message

    informed = [False] * n
    informed[0] = True

    messages = []

    while queue:
        current = queue.popleft()

        # The current student can inform up to a[current] students
        for i in range(current, n):
            if not informed[i] and a[current] > 0 and i != current:
                messages.append((current + 1, i + 1))  # Convert to 1-indexed
                informed[i] = True
                a[current] -= 1
                queue.append(i)
                if a[current] == 0:
                    break  # Current student has no more capacity


    if all(informed):
        print(len(messages))
        for f, t in messages:
            print(f, t)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

