import sys

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)  # 1-indexed
        self.min_indices = [self.n + 1] * (self.n + 1)  # minimum index in each range

    def update(self, index, delta):
        # delta = 1 means standing, delta = -1 means fallen
        while index <= self.n:
            self.tree[index] += delta
            # Update min_index: if delta is 1 and current index is smaller than stored, update
            if delta == 1:
                if index < self.min_indices[index]:
                    self.min_indices[index] = index
            elif delta == -1:
                # If this range no longer has any standing warriors, set to INF
                if self.min_indices[index] == index:
                    self.min_indices[index] = self.n + 1
            index += index & -index

    def query_min_index(self):
        # Find the minimum index where a warrior is standing
        index = 1
        min_standing_index = self.n + 1
        while index <= self.n:
            if self.min_indices[index] < min_standing_index and self.min_indices[index] <= self.n:
                min_standing_index = self.min_indices[index]
            index += index & -index
        return min_standing_index

    def get_sum(self, index):
        # Get total number of standing warriors
        res = 0
        while index > 0:
            res += self.tree[index]
            index -= index & -index
        return res


