def solve():
    n, m = map(int, input().split())

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    a = list(map(int, input().split()))

    # Try each counter as potential button press
    # We'll use backtracking to find a valid solution

    def backtrack():
        pressed = []

        def dfs(p):
            if p == n:
                # Check if this configuration works
                result = [0]*n
                for i in pressed:
                    result[i] += 1
                for i in range(n):
                    for neighbor in adj[i]:
                        result[neighbor] += 1

                for i in range(n):
                    if result[i] == a[i]:
                        return False
                return True

            # Try not pressing
            if dfs(p+1):
                return True

            # Try pressing
            pressed.append(p)
            if dfs(p+1):
                return True
            pressed.pop()
            return False

        return dfs(0)

    # Try all possible solutions
    for solution in range(1 << n):
        # Check if this solution works
        result = [0]*n
        for i in range(n):
            if solution & (1 << i):
                result[i] += 1
        for i in range(n):
            for neighbor in adj[i]:
                result[neighbor] += 1

        valid = True
        for i in range(n):
            if result[i] == a[i]:
                valid = False
                break

        if valid:
            pressed = [i for i in range(n) if solution & (1 << i)]
            print(len(pressed))
            print(' '.join(map(str, [i+1 for i in pressed])))
            return

    print(-1)

