{"code": "
n, m, k = map(int, input().split())
matrix = []
for _ in range(n):
    row = list(map(int, input().split()))
    matrix.append(row)

changes = 0
score = 0

for col in range(m):
    # Find all 1's in this column
    ones_positions = []
    for row in range(n):
        if matrix[row][col] == 1:
            ones_positions.append(row + 1)  # 1-indexed

    if not ones_positions:
        # No 1's in this column
        continue

    max_score = -1
    best_changes = 0

    # Try all possible windows
    for start in range(1, n + 1):
        if start > ones_positions[-1]:
            # No 1's in this window
            continue

        # Find the closest 1 to the left (topmost in the window)
        topmost = None
        for pos in ones_positions:
            if pos >= start:
                topmost = pos
                break

        if topmost is None:
            continue

        # Determine how far we go down
        window_size = min(k, n - start + 1)
        end = min(start + window_size - 1, n)

        # Count 1's in this window
        count = 0
        for pos in range(start, end + 1):
            if matrix[pos - 1][col] == 1:
                count += 1

        # Changes needed = number of 1's not in this window
        # (i.e., we keep the 1's in the window and change the others to 0)
        changes_needed = 0
        for pos in ones_positions:
            if pos < start or pos > end:
                changes_needed += 1

        # Update max score and changes
        if count > max_score or (count == max_score and changes_needed < best_changes):
            max_score = count
            best_changes = changes_needed

    score += max_score
    changes += best_changes

print(score, changes)
