def lcm_string(s: str, t: str) -> str:
    """Find the LCM of two strings s and t."""
    # Generate all possible multiples of s up to some limit
    multiples_of_s = [s * x for x in range(1, 31)]  # 30 repetitions

    # Generate all possible multiples of t up to some limit
    multiples_of_t = [t * x for x in range(1, 31)]

    # Find common multiples
    common_multiples = set(multiples_of_s) & set(multiples_of_t)

    # Return the shortest one, or -1 if none
    if common_multiples:
        return min(common_multiples, key=len)
    else:
        return -1

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    print(lcm_string(s, t))
"}

