MOD = 10**9 + 7

def is_perfect_square(x):
    """Check if x is a perfect square."""
    if x < 0:
        return False
    root = int(x**0.5)
    return root * root == x

def main():
    n = int(input())
    arr = list(map(int, input().split()))

    # Precompute bad pairs
    bad = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if is_perfect_square(arr[i] * arr[j]):
                bad[i][j] = True

    # DP: dp[mask][last] = number of permutations using elements in mask, ending with element last
    dp = [[0] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            for new in range(n):
                if mask & (1 << new):
                    continue
                if not bad[last][new]:
                    dp[mask | (1 << new)][new] = (dp[mask | (1 << new)][new] + dp[mask][last]) % MOD

    result = dp[(1 << n) - 1] % MOD
    print(result)

if __name__ == "__main__":
    main()
"}

