import sys

def is_valid(sequence):
    """Check if a sequence of brackets is valid."""
    stack = []
    for char in sequence:
        if char in "([":
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack.pop()
            if (char == ")" and top != "(") or (char == "]" and top != "["):
                return False
    return len(stack) == 0

def find_optimal_substring(s):
    """Find the optimal valid substring with maximum '['.
    Returns (num_brackets, optimal_sequence)."""
    n = len(s)
    max_opening = 0
    optimal = ""

    # Try all possible substrings
