import math

def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n = int(input())
        k = int(math.isqrt(2 * n - 1))  # floor(sqrt(2n - 1))

        if k < 3:
            results.append(0)
        else:
            # Count of odd numbers from 1 to k: (k + 1) // 2
            # Count from 3 to k = count from 1 to k - 1 (since we exclude 1)
            count = ((k + 1) // 2) - 1
            results.append(count)

    for res in results:
        print(res)

solve()
