import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    w = int(data[0])
    m = int(data[1])
    k = int(data[2])

    def count_digits_sum(n):
        if n == 0:
            return 0
        total = 0
        d = 1
        while True:
            start = 10 ** (d - 1)
            if start > n:
                break
            end = 10 ** d - 1
            count = min(n, end) - start + 1
            total += count * d
            d += 1
        return total

    def total_cost(L):
        if L == 0:
            return 0
        a = m
        b = m + L - 1
        if b < a:
            return 0
        return count_digits_sum(b) - count_digits_sum(a - 1)

    if k == 0:
        print(0)
        return

    max_possible = w // k + 1
    low = 0
    high = max_possible
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        cost = total_cost(mid) * k
        if cost <= w:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

if __name__ == "__main__":
    solve()
