    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    colors = []
    for _ in range(n):
        colors.append(int(next(it)))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    # Build color to vertices mapping
    color_to_vertices = {}
    for i in range(n):
        c = colors[i]
        if c not in color_to_vertices:
            color_to_vertices[c] = []
        color_to_vertices[c].append(i)

    # For each color, find its neighboring colors
    max_neighboring_count = -1
    best_color = -1

    for color, vertices in color_to_vertices.items():
        neighboring_colors = set()
        for vertex in vertices:
            for neighbor_vertex in adj[vertex]:
                neighboring_colors.add(colors[neighbor_vertex])

        count = len(neighboring_colors)

        if count > max_neighboring_count or (count == max_neighboring_count and color < best_color):
            max_neighboring_count = count
            best_color = color

    print(best_color)

