# Read input
N, M = map(int, input().split())

map_a = []
for _ in range(N):
    map_a.append(input().strip())

map_b = []
for _ in range(M):
    map_b.append(input().strip())

# Brute force search
for i in range(N - M + 1):
    # Extract M×M section from map_a starting at row i
    section_a = []
    for r in range(i, i + M):
        section_a.append(map_a[r])

    # Compare with map_b (which has M rows, so we need to check if any column matches)
    for j in range(M - N + 1):
        match = True
        for c in range(N):
            if section_a[c][j] != map_b[c][j]:
                match = False
                break
        if match:
            print(i + 1, j + 1)
            exit()
"}

