import math

def solve():
    n, R, r = map(int, input().split())

    if n == 1:
        # Single plate just needs to fit inside the table
        if r <= R:
            print("YES")
        else:
            print("NO")
        return

    # For n >= 2 plates
    # Check if (R - r) * sin(π/n) >= r
    # Handle floating point precision
    if (R - r) * math.sin(math.pi / n) >= r - 1e-9:
        print("YES")
    else:
        print("NO")

solve()
"}

